from dataclasses import dataclass
from adaptix import Retort, name_mapping, DebugTrail, NameStyle
from adaptix.struct_trail import get_trail
from adaptix.load_error import ExtraFieldsLoadError
@dataclass
class M:
    first_name: int
    other: int = 0
for d in DebugTrail:
 r = Retort(recipe=[name_mapping(M, aliases={'first_name': ['legacy', 'old']}, alias_style=NameStyle.CAMEL)], debug_trail=d)
 assert r.load({'legacy': 3}, M) == M(3)
 assert r.load({'firstName': 4}, M) == M(4)
 assert r.dump(M(2)) == {'first_name': 2, 'other': 0}
 try: r.load({'legacy': 1, 'old': 2}, M)
 except Exception as e:
  errors = getattr(e, 'exceptions', (e,))
  assert any(isinstance(x, ExtraFieldsLoadError) for x in errors)
 else: raise AssertionError('conflict accepted')
print('alias smoke checks passed')
